double uniform_random(double min, double max, unsigned int& seed, unsigned int a, unsigned int c, unsigned int m) {
    // Update seed using LCG formula
    seed = (a * seed + c) % m;

    // Convert to double in [0,1) range
    double normalized = static_cast<double>(seed) / m;

    // Scale to [min, max) range
    return min + normalized * (max - min);
}

